import React from "react";
import { Text, View } from "react-native";
import { useSkeuo } from "../theme";
export function ActivityChart({
  values = [35, 62, 48, 88, 54, 72, 42],
  label = "Hours this week",
}: {
  values?: number[];
  label?: string;
}) {
  const { colors: c } = useSkeuo();
  return (
    <View style={{ gap: 14 }}>
      <View
        accessibilityRole="image"
        accessibilityLabel={`${label}: ${values.join(", ")}`}
        style={{
          height: 140,
          flexDirection: "row",
          gap: 10,
          alignItems: "flex-end",
        }}
      >
        {values.map((value, i) => (
          <View
            key={i}
            style={{
              flex: 1,
              height: "100%",
              justifyContent: "flex-end",
              gap: 7,
            }}
          >
            <View
              style={{
                height: (Math.max(2, Math.min(100, value)) +
                  "%") as `${number}%`,
                backgroundColor: i === 3 ? c.accent : c.edge,
                borderTopLeftRadius: 5,
                borderTopRightRadius: 5,
                borderWidth: 1,
                borderColor: c.base,
              }}
            />
          </View>
        ))}
      </View>
      <View style={{ flexDirection: "row" }}>
        {values.map((_, i) => (
          <Text
            key={i}
            style={{
              flex: 1,
              textAlign: "center",
              color: c.muted,
              fontSize: 10,
            }}
          >
            {["M", "T", "W", "T", "F", "S", "S"][i % 7]}
          </Text>
        ))}
      </View>
    </View>
  );
}

import React, { createContext, useContext } from "react";
import { useColorScheme } from "nativewind";
import * as Haptics from "expo-haptics";

export const themes = {
  light: {
    background: "#ffffff",
    surface: "#f5f5f2",
    raised: "#fafaf8",
    well: "#e9e9e5",
    edge: "#d1d1cb",
    base: "#d9d9d3",
    ink: "#202020",
    muted: "#686863",
    accent: "#365e50",
    accentInk: "#ffffff",
  },
  dark: {
    background: "#000000",
    surface: "#191919",
    raised: "#252525",
    well: "#111111",
    edge: "#3b3b39",
    base: "#080808",
    ink: "#efefeb",
    muted: "#aaaAA5",
    accent: "#9ab5a6",
    accentInk: "#14251c",
  },
};
type ThemeState = { colors: typeof themes.light; dark: boolean; haptics: boolean; onSound?: () => void };
const Context = createContext<ThemeState | null>(null);
export function SkeuoProvider({
  children,
  appearance = "system",
  haptics = false,
  onSound,
  colors: overrides,
}: {
  children: React.ReactNode;
  appearance?: "light" | "dark" | "system";
  haptics?: boolean;
  onSound?: () => void;
  colors?: Partial<typeof themes.light>;
}) {
  const { colorScheme: system } = useColorScheme();
  const dark = (appearance === "system" ? system : appearance) === "dark";
  return (
    <Context.Provider
      value={{
        colors: { ...(dark ? themes.dark : themes.light), ...overrides },
        dark,
        haptics,
        onSound,
      }}
    >
      {children}
    </Context.Provider>
  );
}
export function useSkeuo(): ThemeState {
  const context = useContext(Context);
  const { colorScheme } = useColorScheme();
  return context ?? { colors: colorScheme === "dark" ? themes.dark : themes.light, dark: colorScheme === "dark", haptics: false };
}
export function useFeedback() {
  const { haptics, onSound } = useSkeuo();
  return () => {
    onSound?.();
    if (haptics) void Haptics.selectionAsync().catch(() => {});
  };
}
